mapper.select:
SELECT cm.id AS message_id, cm.project_id, cm.sender_id, u.name AS sender_name, u.profile_image_url AS sender_profile_image_url, cm.content, cm.type, cm.created_at FROM chat_messages cm JOIN users u ON u.id = cm.sender_id WHERE cm.project_id = #{projectId}
AND cm.id < #{beforeId}
ORDER BY cm.id DESC LIMIT #{limit}
